   202→            Err(e) => handle_error(e, reader.get_ref().get_ref().position(), max_compressed_len),
   203→        }
   204→    }
   205→}
   206→
   207→/* Outbound Codec: Codec for initiating RPC requests */
   208→pub struct SSZSnappyOutboundCodec<E: EthSpec> {
   209→    inner: Uvi<usize>,
   210→    len: Option<usize>,
   211→    protocol: ProtocolId,
   212→    /// Maximum bytes that can be sent in one req/resp chunked responses.
